async function scanBundle(input, deliver) {
  const decoder = new TextDecoder("utf-8", { fatal: true });
  let buffer = "";
  let line = 1;
  let delivered = 0;
  let stopped = false;

  const processLine = async (text, lineNumber) => {
    if (text.endsWith("\r")) text = text.slice(0, -1);
    if (text.trim() === "") return;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error(`Invalid JSON on line ${lineNumber}`);
      error.code = "BAD_LINE";
      error.line = lineNumber;
      throw error;
    }

    const result = await deliver(value, lineNumber);
    delivered++;
    if (result === false) stopped = true;
  };

  try {
    while (!stopped) {
      const chunk = await input.read();

      if (chunk === null) {
        buffer += decoder.decode();
        if (buffer.length > 0) {
          await processLine(buffer, line);
        }
        break;
      }

      buffer += decoder.decode(chunk, { stream: true });

      let newline;
      while (!stopped && (newline = buffer.indexOf("\n")) !== -1) {
        const currentLine = buffer.slice(0, newline);
        buffer = buffer.slice(newline + 1);
        await processLine(currentLine, line);
        line++;
      }
    }

    return delivered;
  } finally {
    await input.close();
  }
}
